/**
 * generated by stackra gen from the `offline` option of each consumed `@Action` (the producers'
 * committed manifests) — do not edit
 * Purpose: the offline map: for each compiled action, what the mutation queue of @stackra/query may
 *          do with it while the device is offline.
 * Boundary: data the query module reads at boot. `Queue` actions are held in the `outbox` store
 *           with their Idempotency-Key and precondition; `Online` actions refuse with `offline` at
 *           once. An action the producer declares no `offline` for is online-only and is not
 *           listed.
 * Runtime: react-native
 */
import {
  ConflictResolution,
  IdMinting,
  OfflineMode,
  OfflinePrecondition,
} from "@stackra/actions";
import { offlineMap } from "@stackra/query";
import { Commerce, Devices } from "#stackra/clients";

/** Action → offline policy, exactly as each producer's manifest declares it. */
export const Offline = offlineMap([
  {
    action: Commerce.actions.CreateOrder,
    mode: OfflineMode.Queue,
    idMinting: IdMinting.Client,
    precondition: OfflinePrecondition.None,
    retention: "72h",
    onConflict: [ConflictResolution.ServerWins, ConflictResolution.Manual],
  },
  {
    action: Devices.actions.RegisterDevice,
    mode: OfflineMode.Queue,
    idMinting: IdMinting.Server,
    precondition: OfflinePrecondition.None,
    retention: "24h",
    onConflict: [ConflictResolution.ServerWins],
  },
]);
